import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-javascript-bind-function-context":{"intro":"In this lab, we will explore how to create a function that binds a given context to another function. The bind() function allows us to easily set the value of this within a function to a specific object, which can be useful in certain scenarios. We will learn how to use the spread operator to pass additional arguments to the bound function as well.","steps":[{"title":"Bind Function Context","body":["Creating a Function with a Given Context","The bind function creates a new function that invokes the original function with a given context. It can also optionally prepend any additional supplied parameters to the arguments.","To use bind, pass in the original function (fn) and the desired context (context). You can also pass in any additional parameters that should be bound to the function (...boundArgs).","The bind function returns a new function that uses Function.prototype.apply() to apply the given context to fn. It also uses the spread operator (...) to prepend any additional supplied parameters to the arguments."],"code":[{"lang":"js","text":"const bind =\n  (fn, context, ...boundArgs) =>\n  (...args) =>\n    fn.apply(context, [...boundArgs, ...args]);\n\nfunction greet(greeting, punctuation) {\n  return greeting + \" \" + this.user + punctuation;\n}\n\nconst freddy = { user: \"fred\" };\nconst freddyBound = bind(greet, freddy);\nconsole.log(freddyBound(\"hi\", \"!\")); // 'hi fred!'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const bind =\n  (fn, context, ...boundArgs) =>\n  (...args) =>\n    fn.apply(context, [...boundArgs, ...args]);\n\nfunction greet(greeting, punctuation) {\n  return greeting + \" \" + this.user + punctuation;\n}\n\nconst freddy = { user: \"fred\" };\nconst freddyBound = bind(greet, freddy);\nconsole.log(freddyBound(\"hi\", \"!\")); // 'hi fred!'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-bind-object-method":{"intro":"In this lab, we will explore the concept of binding object methods in JavaScript. We will create a function that binds a given method of an object to the context of that object, allowing us to call the method with any additional arguments we provide. By the end of this lab, you will have a deeper understanding of how to manipulate objects and their methods in JavaScript.","steps":[{"title":"Bind Object Method","body":["Function to Bind Object Method","To create a function that binds an object method to its context and optionally prepends additional parameters, follow these steps:","• To test the function, create an object with a method and bind it using bindKey(). Then, call the bound method with some arguments."],"code":[{"lang":"js","text":"const bindKey =\n  (context, fn, ...boundArgs) =>\n  (...args) =>\n    context[fn].apply(context, [...boundArgs, ...args]);"},{"lang":"js","text":"const freddy = {\n  user: \"fred\",\n  greet: function (greeting, punctuation) {\n    return greeting + \" \" + this.user + punctuation;\n  }\n};\nconst freddyBound = bindKey(freddy, \"greet\");\nconsole.log(freddyBound(\"hi\", \"!\")); // 'hi fred!'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const freddy = {\n  user: \"fred\",\n  greet: function (greeting, punctuation) {\n    return greeting + \" \" + this.user + punctuation;\n  }\n};\nconst freddyBound = bindKey(freddy, \"greet\");\nconsole.log(freddyBound(\"hi\", \"!\")); // 'hi fred!'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-javascript-programming-fundamentals":{"intro":"In this lab, we will dive into the world of JavaScript programming and learn how to write efficient and effective code. Through a series of hands-on exercises and challenges, you will gain a solid understanding of fundamental programming concepts such as variables, functions, loops, and conditional statements. By the end of this lab, you will have the skills and confidence to tackle real-world programming problems using JavaScript.","steps":[{"title":"Binomial Coefficient","body":["Binomial Coefficient Calculation","To calculate the number of ways to choose k items from n items without repetition and without order, you can use the following JavaScript function:","To ensure the function works correctly, you can follow these steps:","• Use Number.isNaN() to check if any of the two values is NaN. • Check if k is less than 0, greater than or equal to n, equal to 1 or n - 1 and return the appropriate result. • Check if n - k is less than k and switch their values accordingly. • Loop from 2 through k and calculate the binomial coefficient. • Use Math.round() to account for rounding errors in the calculation."],"code":[{"lang":"js","text":"const binomialCoefficient = (n, k) => {\n  if (Number.isNaN(n) || Number.isNaN(k)) return NaN;\n  if (k < 0 || k > n) return 0;\n  if (k === 0 || k === n) return 1;\n  if (k === 1 || k === n - 1) return n;\n  if (n - k < k) k = n - k;\n  let res = n;\n  for (let j = 2; j <= k; j++) res *= (n - j + 1) / j;\n  return Math.round(res);\n};"},{"lang":"js","text":"binomialCoefficient(8, 2); // 28"}]}],"commands":[],"reference":[{"path":"reference.js","text":"binomialCoefficient(8, 2); // 28"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-bubble-sort-algorithm-in-javascript":{"intro":"In this lab, we will be working on a JavaScript programming exercise that focuses on sorting arrays using the bubble sort algorithm. The purpose of this lab is to help you understand how the bubble sort algorithm works, as well as to give you an opportunity to practice your JavaScript programming skills. By the end of this lab, you will have a better understanding of how to implement the bubble sort algorithm in JavaScript, and how to use it to sort arrays of numbers.","steps":[{"title":"Bubble Sort","body":["Steps to sort an array using the bubble sort algorithm:","• Declare a variable, swapped, that indicates if any values were swapped during the current iteration.","• Use the spread operator (...) to clone the original array, arr.","• Use a for loop to iterate over the elements of the cloned array, terminating before the last element."],"code":[{"lang":"js","text":"const bubbleSort = (arr) => {\n  let swapped = false;\n  const a = [...arr];\n  for (let i = 1; i < a.length; i++) {\n    swapped = false;\n    for (let j = 0; j < a.length - i; j++) {\n      if (a[j + 1] < a[j]) {\n        [a[j], a[j + 1]] = [a[j + 1], a[j]];\n        swapped = true;\n      }\n    }\n    if (!swapped) return a;\n  }\n  return a;\n};\n\nbubbleSort([2, 1, 4, 3]); // [1, 2, 3, 4]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const bubbleSort = (arr) => {\n  let swapped = false;\n  const a = [...arr];\n  for (let i = 1; i < a.length; i++) {\n    swapped = false;\n    for (let j = 0; j < a.length - i; j++) {\n      if (a[j + 1] < a[j]) {\n        [a[j], a[j + 1]] = [a[j + 1], a[j]];\n        swapped = true;\n      }\n    }\n    if (!swapped) return a;\n  }\n  return a;\n};\n\nbubbleSort([2, 1, 4, 3]); // [1, 2, 3, 4]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-implementing-bucket-sort-in-javascript":{"intro":"In this lab, we will explore the bucket sort algorithm in JavaScript. Bucket sort is a sorting algorithm that works by distributing the elements of an array into a number of buckets. Each bucket is then sorted individually, either using a different sorting algorithm or by recursively applying the bucket sorting algorithm. This lab will provide you with an opportunity to implement this algorithm and gain a deeper understanding of how it works.","steps":[{"title":"Bucket Sort","body":["To use the bucket sort algorithm and sort an array of numbers, follow these steps:","Here is an example implementation of the bucket sort algorithm in JavaScript:","To test the algorithm, run the following code:"],"code":[{"lang":"js","text":"const bucketSort = (arr, size = 5) => {\n  const min = Math.min(...arr);\n  const max = Math.max(...arr);\n  const buckets = Array.from(\n    { length: Math.floor((max - min) / size) + 1 },\n    () => []\n  );\n  arr.forEach((val) => {\n    buckets[Math.floor((val - min) / size)].push(val);\n  });\n  return buckets.reduce((acc, b) => [...acc, ...b.sort((a, b) => a - b)], []);\n};"},{"lang":"js","text":"bucketSort([6, 3, 4, 1]); // [1, 3, 4, 6]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"bucketSort([6, 3, 4, 1]); // [1, 3, 4, 6]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-calculating-string-byte-size":{"intro":"In this lab, we will explore how to calculate the byte size of a given string using JavaScript. The purpose of this lab is to help you understand how to convert a string into a Blob object and obtain its size in bytes using the Blob.size property. This knowledge can be useful in various scenarios, such as when working with network requests or file uploads, where byte size is an essential factor to consider.","steps":[{"title":"Understanding JavaScript String Representation","body":["Understanding JavaScript String Representation","Before we calculate the byte size of strings, it is important to understand how strings are represented in JavaScript.","In JavaScript, strings are sequences of UTF-16 code units. This means that characters like emojis or certain symbols may take more than one byte to represent. For example, a simple English letter takes 1 byte, but an emoji might take 4 bytes.","You should now be in the Node.js interactive console, which looks something like this:"],"code":[{"lang":"text","text":"Welcome to Node.js v14.x.x.\nType \".help\" for more information.\n>"},{"lang":"javascript","text":"\"Hello World\".length;"}]},{"title":"Using Blob to Calculate String Byte Size","body":["Using Blob to Calculate String Byte Size","Now that we understand string representation, let's learn how to calculate the actual byte size of a string using the Blob object.","A Blob (Binary Large Object) represents a file-like object of immutable, raw data. By converting our string to a Blob, we can access its size property to determine the byte size.","In the Node.js console, let's create a function to calculate the byte size:"],"code":[{"lang":"javascript","text":"const byteSize = (str) => new Blob([str]).size;"},{"lang":"javascript","text":"byteSize(\"Hello World\");"},{"lang":"javascript","text":"byteSize(\"😀\");"}]},{"title":"Testing with Different String Types","body":["Testing with Different String Types","Let's explore how different types of characters affect the byte size of a string.","In the Node.js console, let's test our byteSize function with various strings:","• Numbers and special characters:"],"code":[{"lang":"javascript","text":"byteSize(\"The quick brown fox jumps over the lazy dog\");"},{"lang":"javascript","text":"byteSize(\"123!@#$%^&*()\");"},{"lang":"javascript","text":"byteSize(\"Hello, 世界！\");"}]},{"title":"Creating a Practical Example File","body":["Creating a Practical Example File","Now let's create a JavaScript file to implement our byte size function in a more practical way. This will demonstrate how you might use this function in a real-world application.","• Add the following code to the file:","• Save the file by pressing Ctrl+S or by selecting File > Save from the menu."],"code":[{"lang":"javascript","text":"/**\n * Calculate the byte size of a given string.\n * @param {string} str - The string to calculate the byte size for.\n * @returns {number} The size in bytes.\n */\nfunction calculateByteSize(str) {\n  return new Blob([str]).size;\n}\n\n// Examples with different types of strings\nconst examples = [\n  \"Hello World\",\n  \"😀\",\n  \"The quick brown fox jumps over the lazy dog\",\n  \"123!@#$%^&*()\",\n  \"Hello, 世界！\",\n  \"😀😃😄😁\"\n];\n\n// Display the results\nconsole.log(\"String Byte Size Calculator\\n\");\nconsole.log(\"String\".padEnd(45) + \"| Characters | Bytes\");\nconsole.log(\"-\".repeat(70));\n\nexamples.forEach((example) => {\n  console.log(\n    `\"${example}\"`.padEnd(45) +\n      `| ${example.length}`.padEnd(12) +\n      `| ${calculateByteSize(example)}`\n  );\n});"},{"lang":"bash","text":"node byteSizeCalculator.js"},{"lang":"text","text":"String Byte Size Calculator\n\nString                                      | Characters | Bytes\n----------------------------------------------------------------------\n\"Hello World\"                               | 11         | 11\n\"😀\"                                        | 1          | 4\n\"The quick brown fox jumps over the lazy dog\" | 43         | 43\n\"123!@#$%^&*()\"                            | 13         | 13\n\"Hello, 世界!\"                              | 10         | 13\n\"😀😃😄😁\"                                  | 4          | 16"}]}],"commands":["node byteSizeCalculator.js"],"reference":[{"path":"reference.txt","text":"String Byte Size Calculator\n\nString                                      | Characters | Bytes\n----------------------------------------------------------------------\n\"Hello World\"                               | 11         | 11\n\"😀\"                                        | 1          | 4\n\"The quick brown fox jumps over the lazy dog\" | 43         | 43\n\"123!@#$%^&*()\"                            | 13         | 13\n\"Hello, 世界!\"                              | 10         | 13\n\"😀😃😄😁\"                                  | 4          | 16"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-implementing-caesar-cipher-in-javascript":{"intro":"In this lab, we will explore the Caesar cipher, a simple encryption algorithm that shifts each letter of a given string by a certain number of positions down the alphabet. We will implement the Caesar cipher in JavaScript, using a combination of string manipulation and array methods, and learn how to encrypt and decrypt messages with this technique. This lab is an excellent opportunity to practice your JavaScript skills and gain a better understanding of encryption algorithms.","steps":[{"title":"Caesar Cipher","body":["To use the Caesar cipher, follow these steps:","Here is the code for the caesarCipher function:","Here are some examples of how to use the caesarCipher function:"],"code":[{"lang":"js","text":"const caesarCipher = (str, shift, decrypt = false) => {\n  const s = decrypt ? (26 - shift) % 26 : shift;\n  const n = s > 0 ? s : 26 + (s % 26);\n  return [...str]\n    .map((l, i) => {\n      const c = str.charCodeAt(i);\n      if (c >= 65 && c <= 90)\n        return String.fromCharCode(((c - 65 + n) % 26) + 65);\n      if (c >= 97 && c <= 122)\n        return String.fromCharCode(((c - 97 + n) % 26) + 97);\n      return l;\n    })\n    .join(\"\");\n};"},{"lang":"js","text":"caesarCipher(\"Hello World!\", -3); // 'Ebiil Tloia!'\ncaesarCipher(\"Ebiil Tloia!\", 23, true); // 'Hello World!'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"caesarCipher(\"Hello World!\", -3); // 'Ebiil Tloia!'\ncaesarCipher(\"Ebiil Tloia!\", 23, true); // 'Hello World!'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-call-or-return":{"intro":"In this lab, we will learn about the callOrReturn function, which is a useful utility function in JavaScript. This function can be used to determine whether the given argument is a function or not. If the argument is a function, it will be called with the rest of the arguments. Otherwise, it will simply return the given argument. By the end of this lab, you will be able to use this function to simplify your code and improve its readability.","steps":[{"title":"Call or Return","body":["A Function That Calls or Returns Another Function","Here's a function called callOrReturn that takes an argument and calls it if it's a function, otherwise, it returns it. Here's how it works:","• The function takes two parameters: fn and ...args. fn is the argument to be checked, and ...args is the list of arguments to be passed to the function if it's called. • It uses the typeof operator to check if the given argument is a function. • If the argument is indeed a function, it calls the function using the spread operator (...) to pass the rest of the given arguments. Otherwise, it simply returns the argument. • Here's an example of how to use the callOrReturn function:","In the first example, callOrReturn(x => x + 1, 1) calls the function x => x + 1 with the argument 1, which returns 2. In the second example, callOrReturn(1, 1) simply returns 1 since it's not a function."],"code":[{"lang":"js","text":"const callOrReturn = (fn, ...args) =>\n  typeof fn === \"function\" ? fn(...args) : fn;\n\ncallOrReturn((x) => x + 1, 1); // 2\ncallOrReturn(1, 1); // 1"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const callOrReturn = (fn, ...args) =>\n  typeof fn === \"function\" ? fn(...args) : fn;\n\ncallOrReturn((x) => x + 1, 1); // 2\ncallOrReturn(1, 1); // 1"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-capitalize-first-letter-in-javascript":{"intro":"In this lab, we will explore a JavaScript function called capitalize that capitalizes the first letter of a string. The function uses array destructuring and String.prototype.toUpperCase() to achieve the desired result. We will also see how to use the lowerRest argument to convert the rest of the string to lowercase if needed.","steps":[{"title":"Capitalize String","body":["JavaScript Function to Capitalize First Letter of a String","To capitalize the first letter of a string in JavaScript, use the following function:","This function uses array destructuring and String.prototype.toUpperCase() to capitalize the first letter of the string. The lowerRest argument is optional and can be set to true to convert the rest of the string to lowercase.","Here is an example of how to use this function:"],"code":[{"lang":"js","text":"const capitalize = (str, lowerRest = false) => {\n  const [first, ...rest] = str;\n  return (\n    first.toUpperCase() +\n    (lowerRest ? rest.join(\"\").toLowerCase() : rest.join(\"\"))\n  );\n};"},{"lang":"js","text":"capitalize(\"fooBar\"); // 'FooBar'\ncapitalize(\"fooBar\", true); // 'Foobar'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"capitalize(\"fooBar\"); // 'FooBar'\ncapitalize(\"fooBar\", true); // 'Foobar'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-fundamentals-of-javascript-programming":{"intro":"In this lab, we will explore the fundamental concepts of JavaScript programming. The purpose of this lab is to provide hands-on experience to learners who are new to JavaScript programming. Through a series of exercises and challenges, learners will gain a solid understanding of the basics of the language, including variables, data types, operators, and control flow. The lab is designed to be interactive and engaging, with plenty of opportunities to practice coding and receive feedback along the way.","steps":[{"title":"Capitalize Every Word","body":["How to Capitalize Every Word in JavaScript","To capitalize every word in a string using JavaScript, you can use the String.prototype.replace() method to match the first character of each word, and then use the String.prototype.toUpperCase() method to capitalize it.","Here's an example code snippet you can use:","To use this function, pass in the string you want to capitalize as an argument, like this:"],"code":[{"lang":"js","text":"const capitalizeEveryWord = (str) =>\n  str.replace(/\\b[a-z]/g, (char) => char.toUpperCase());"},{"lang":"js","text":"capitalizeEveryWord(\"hello world!\"); // 'Hello World!'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"capitalizeEveryWord(\"hello world!\"); // 'Hello World!'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-calculating-cartesian-product-with-javascrip":{"intro":"In this lab, we will explore the concept of Cartesian Product and how to calculate it using JavaScript. We will learn how to use the Array.prototype.reduce(), Array.prototype.map() and the spread operator (...) to generate all possible element pairs from two arrays. By the end of the lab, you will have a better understanding of how to use these methods to calculate the Cartesian Product of two arrays.","steps":[{"title":"Cartesian Product","body":["To calculate the cartesian product of two arrays, follow these steps:","This will generate all possible combinations of elements from the two arrays."],"code":[{"lang":"js","text":"const cartesianProduct = (a, b) =>\n  a.reduce((p, x) => [...p, ...b.map((y) => [x, y])], []);"},{"lang":"js","text":"cartesianProduct([\"x\", \"y\"], [1, 2]);\n// [['x', 1], ['x', 2], ['y', 1], ['y', 2]]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"cartesianProduct([\"x\", \"y\"], [1, 2]);\n// [['x', 1], ['x', 2], ['y', 1], ['y', 2]]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-cast-to-array":{"intro":"In this lab, we will explore the castArray() function in JavaScript. The purpose of the lab is to understand how to convert a non-array value to an array with a single line of code. By the end of this lab, you will have a clear understanding of how to use the castArray() function to manipulate data structures in JavaScript.","steps":[{"title":"Cast to Array","body":["Converting Values to Arrays in JavaScript","To convert a value into an array, use the castArray function provided below.","To use this function, pass the value you want to convert as the argument. The function will check if the value is already an array using Array.isArray(). If it is an array, the function will return it as-is. If it is not an array, the function will return the value encapsulated in an array.","Here's an example of how to use castArray:"],"code":[{"lang":"js","text":"const castArray = (val) => (Array.isArray(val) ? val : [val]);"},{"lang":"js","text":"castArray(\"foo\"); // returns: ['foo']\ncastArray([1]); // returns: [1]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"castArray(\"foo\"); // returns: ['foo']\ncastArray([1]); // returns: [1]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-convert-temperature-units":{"intro":"Sure, here's an introduction for a JavaScript programming lab:","steps":[{"title":"Celsius to Fahrenheit","body":["Conversion of Celsius to Fahrenheit","To convert Celsius to Fahrenheit using coding, follow these steps:","• Test the function by entering a value in degrees Celsius, like this:","This will output the corresponding value in degrees Fahrenheit."],"code":[{"lang":"js","text":"const celsiusToFahrenheit = (degrees) => 1.8 * degrees + 32;"},{"lang":"js","text":"celsiusToFahrenheit(33); // 91.4"}]}],"commands":[],"reference":[{"path":"reference.js","text":"celsiusToFahrenheit(33); // 91.4"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-change-color-lightness":{"intro":"In this lab, we will be exploring how to change the lightness of an hsl() color string using JavaScript. By leveraging string manipulation, array methods, and mathematical functions, we will learn how to modify the lightness value while ensuring that it stays within the valid range of 0 to 100. This skill will come in handy when developing web applications that require dynamic color manipulations based on user interactions.","steps":[{"title":"Change Color Lightness","body":["How to Change the Lightness of an HSL Color","To change the lightness value of an hsl() color string, follow these steps:","• Use String.prototype.match() to get an array of three strings with the numeric values from the hsl() string.","• Use Array.prototype.map() in combination with Number to convert the strings into an array of numeric values."],"code":[{"lang":"js","text":"const changeLightness = (delta, hslStr) => {\n  const [hue, saturation, lightness] = hslStr.match(/\\d+/g).map(Number);\n\n  const newLightness = Math.max(\n    0,\n    Math.min(100, lightness + parseFloat(delta))\n  );\n\n  return `hsl(${hue}, ${saturation}%, ${newLightness}%)`;\n};"},{"lang":"js","text":"changeLightness(10, \"hsl(330, 50%, 50%)\"); // 'hsl(330, 50%, 60%)'\nchangeLightness(-10, \"hsl(330, 50%, 50%)\"); // 'hsl(330, 50%, 40%)'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"changeLightness(10, \"hsl(330, 50%, 50%)\"); // 'hsl(330, 50%, 60%)'\nchangeLightness(-10, \"hsl(330, 50%, 50%)\"); // 'hsl(330, 50%, 40%)'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-chunking-iterables-into-smaller-arrays":{"intro":"In this lab, we will explore the concept of chunking an iterable into smaller arrays of a specified size using JavaScript. We will implement a function that takes in an iterable and a size parameter and returns an iterable of smaller arrays that contain a maximum of size elements each. This technique can be useful for various applications, such as breaking down large datasets into smaller chunks for processing or optimizing network requests by reducing the amount of data transferred at once.","steps":[{"title":"Chunk Iterable","body":["To chunk an iterable into smaller arrays of a specified size, follow these steps:","• Use this code to test the function:"],"code":[{"lang":"js","text":"const chunkify = function* (itr, size) {\n  let chunk = [];\n  for (const v of itr) {\n    chunk.push(v);\n    if (chunk.length === size) {\n      yield chunk;\n      chunk = [];\n    }\n  }\n  if (chunk.length) yield chunk;\n};"},{"lang":"js","text":"const x = new Set([1, 2, 1, 3, 4, 1, 2, 5]);\n[...chunkify(x, 2)]; // [[1, 2], [3, 4], [5]]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const x = new Set([1, 2, 1, 3, 4, 1, 2, 5]);\n[...chunkify(x, 2)]; // [[1, 2], [3, 4], [5]]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-clamping-numbers-in-javascript":{"intro":"In this lab, we will explore the concept of clamping a number within a specified range in JavaScript. The purpose of this lab is to help you understand how to limit the value of a number to a certain range, which is a common programming task in various applications. By the end of this lab, you will have a clear understanding of how to implement the clampNumber function in your JavaScript code.","steps":[{"title":"Clamp Number","body":["Function to Clamp a Number within a Range","To clamp a number within a specified range, use the clampNumber function.","The clampNumber function takes in three parameters: num, a, and b. It clamps num within the inclusive range specified by the boundary values a and b and returns the result.","If num falls within the range, the function returns num. Otherwise, it returns the nearest number in the range."],"code":[{"lang":"js","text":"const clampNumber = (num, a, b) =>\n  Math.max(Math.min(num, Math.max(a, b)), Math.min(a, b));"},{"lang":"js","text":"clampNumber(2, 3, 5); // 3\nclampNumber(1, -1, -5); // -1"}]}],"commands":[],"reference":[{"path":"reference.js","text":"clampNumber(2, 3, 5); // 3\nclampNumber(1, -1, -5); // -1"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-closest-numeric-match":{"intro":"In this lab, we will explore how to find the closest number from an array using JavaScript. We will use the Array.prototype.reduce() method and the Math.abs() function to compare the distance between each element in the array and a target value, returning the closest match. By the end of this lab, you will have a better understanding of how to implement this useful function in your JavaScript projects.","steps":[{"title":"Closest Numeric Match","body":["A Function to Find the Closest Numeric Match in an Array","To find the closest number in an array, use the following function:","Example usage: closest([6, 1, 3, 7, 9], 5) will return 6, which is the closest number to 5 in the array."],"code":[{"lang":"js","text":"const closest = (arr, n) =>\n  arr.reduce((acc, num) => (Math.abs(num - n) < Math.abs(acc - n) ? num : acc));"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const closest = (arr, n) =>\n  arr.reduce((acc, num) => (Math.abs(num - n) < Math.abs(acc - n) ? num : acc));"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-efficiently-check-empty-javascript-collectio":{"intro":"In this lab, we will explore a common programming problem of checking if a collection or object is empty in JavaScript. We will use a simple function to determine if the provided value is an empty object/collection, has no enumerable properties, or is any type that is not considered a collection. This lab will help you understand how to efficiently check for empty objects or collections in your JavaScript code.","steps":[{"title":"Collection Is Empty","body":["Checking if a Collection is Empty","To use the program, check if the provided value is null or if its length is equal to 0. Here's an example code:","You can then test the program using the following codes:"],"code":[{"lang":"js","text":"const isEmpty = (val) => val == null || !(Object.keys(val) || val).length;"},{"lang":"js","text":"isEmpty([]); // true\nisEmpty({}); // true\nisEmpty(\"\"); // true\nisEmpty([1, 2]); // false\nisEmpty({ a: 1, b: 2 }); // false\nisEmpty(\"text\"); // false\nisEmpty(123); // true - type is not considered a collection\nisEmpty(true); // true - type is not considered a collection"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isEmpty([]); // true\nisEmpty({}); // true\nisEmpty(\"\"); // true\nisEmpty([1, 2]); // false\nisEmpty({ a: 1, b: 2 }); // false\nisEmpty(\"text\"); // false\nisEmpty(123); // true - type is not considered a collection\nisEmpty(true); // true - type is not considered a collection"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-combine-object-arrays":{"intro":"In this lab, we will be working on a JavaScript programming exercise aimed at combining two arrays of objects based on a specified property. The purpose of this exercise is to help you practice using the Array.prototype.reduce() method and object manipulation in JavaScript, which are essential skills for any developer working with JavaScript. By the end of this lab, you should be able to seamlessly combine two arrays of objects based on a property to create a new array.","steps":[{"title":"Combine Object Arrays","body":["Function to Combine Object Arrays Based on a Specified Key","To combine two arrays of objects based on a specific key, follow these steps:","Here's the function that you can use:","Here's an example of how to use this function:"],"code":[{"lang":"js","text":"const combine = (a, b, prop) =>\n  Object.values(\n    [...a, ...b].reduce((acc, v) => {\n      if (v[prop])\n        acc[v[prop]] = acc[v[prop]] ? { ...acc[v[prop]], ...v } : { ...v };\n      return acc;\n    }, {})\n  );"},{"lang":"js","text":"const x = [\n  { id: 1, name: \"John\" },\n  { id: 2, name: \"Maria\" }\n];\nconst y = [{ id: 1, age: 28 }, { id: 3, age: 26 }, { age: 3 }];\ncombine(x, y, \"id\");\n// [\n//  { id: 1, name: 'John', age: 28 },\n//  { id: 2, name: 'Maria' },\n//  { id: 3, age: 26 }\n// ]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const x = [\n  { id: 1, name: \"John\" },\n  { id: 2, name: \"Maria\" }\n];\nconst y = [{ id: 1, age: 28 }, { id: 3, age: 26 }, { age: 3 }];\ncombine(x, y, \"id\");\n// [\n//  { id: 1, name: 'John', age: 28 },\n//  { id: 2, name: 'Maria' },\n//  { id: 3, age: 26 }\n// ]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-finding-common-object-keys-in-javascript":{"intro":"In this lab, we will be exploring a JavaScript function that helps us find the common keys between two objects. We will use the Object.keys() method to get the keys of the first object, and then check if the second object has a key that matches using Object.prototype.hasOwnProperty(). Finally, we will use Array.prototype.filter() to filter out the keys that are not common to both objects. By the end of this lab, you will have a solid understanding of how to efficiently find common keys between two objects in JavaScript.","steps":[{"title":"Common Keys","body":["Tips for Coding and Finding Common Keys","To find the common keys between two objects, follow these steps:","• Use Object.keys() to get the keys of the first object. • Use Object.prototype.hasOwnProperty() to check if the second object has a key that's in the first object. • Use Array.prototype.filter() to filter out keys that aren't in both objects.","Here's an example of the code:"],"code":[{"lang":"js","text":"const commonKeys = (obj1, obj2) =>\n  Object.keys(obj1).filter((key) => obj2.hasOwnProperty(key));"},{"lang":"js","text":"commonKeys({ a: 1, b: 2 }, { a: 2, c: 1 }); // ['a']"}]}],"commands":[],"reference":[{"path":"reference.js","text":"commonKeys({ a: 1, b: 2 }, { a: 2, c: 1 }); // ['a']"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-filtering-falsy-values-in-javascript-arrays":{"intro":"In this lab, we will delve into the concept of working with arrays in JavaScript. You will learn how to use the Array.prototype.filter() method to remove falsy values from an array. By the end of this lab, you will have a better understanding of how to manipulate arrays in JavaScript and be able to apply this knowledge to your own projects.","steps":[{"title":"Compact Array","body":["How to Use Array.prototype.filter() to Create a Compact Array","To create a compact array in JavaScript, you can use the Array.prototype.filter() method to remove any falsy values from the array. Falsy values include false, null, 0, \"\", undefined, and NaN.","Here's an example code snippet that demonstrates how to create a compact array using Array.prototype.filter():","You can then use the compact function to create a compact array by passing in an array as an argument. For example:"],"code":[{"lang":"js","text":"const compact = (arr) => arr.filter(Boolean);"},{"lang":"js","text":"compact([0, 1, false, 2, \"\", 3, \"a\", \"e\" * 23, NaN, \"s\", 34]);\n// Output: [ 1, 2, 3, 'a', 's', 34 ]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"compact([0, 1, false, 2, \"\", 3, \"a\", \"e\" * 23, NaN, \"s\", 34]);\n// Output: [ 1, 2, 3, 'a', 's', 34 ]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-compact-and-join-array":{"intro":"In this lab, we will be exploring the compactJoin function in JavaScript. This function allows you to remove falsy values from an array and join the remaining values into a string. You will learn how to implement this function using Array.prototype.filter() and Array.prototype.join(). By the end of this lab, you will have a better understanding of how to manipulate arrays in JavaScript.","steps":[{"title":"Compact and Join Array","body":["Here's a tip on how to Compact and Join an Array","Here's how to remove falsy values from an array and combine the remaining values into a string:","• Use Array.prototype.filter() to filter out falsy values such as false, null, 0, \"\", undefined, and NaN. • Use Array.prototype.join() to join the remaining values into a string.","Then call the function and pass an array as an argument:"],"code":[{"lang":"js","text":"const compactJoin = (arr, delim = \",\") => arr.filter(Boolean).join(delim);"},{"lang":"js","text":"compactJoin([\"a\", \"\", \"b\", \"c\"]); // 'a,b,c'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"compactJoin([\"a\", \"\", \"b\", \"c\"]); // 'a,b,c'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-recursive-falsy-value-removal-in-javascript":{"intro":"In this lab, we will explore how to use recursion to deeply remove all falsy values from an object or array in JavaScript. We will create a function that takes an object or array as input and returns a new, compacted object or array with only truthy values. This technique can be useful for data cleaning and simplification in various programming applications.","steps":[{"title":"Compact Object","body":["To deeply remove all falsy values from an object or array, use the following algorithm:","• Use recursion to call the compactObject() function on each nested object or array. • Initialize the iterable data using Array.isArray(), Array.prototype.filter(), and Boolean(). This is done to avoid sparse arrays. • Use Object.keys() and Array.prototype.reduce() to iterate over each key with an appropriate initial value. • Use Boolean() to determine the truthiness of each key's value and add it to the accumulator if it's truthy. • Use typeof to determine if a given value is an object and call the function again to deeply compact it.","Here's the code for the compactObject() function:","To use this function, pass an object or array as an argument to compactObject(). The function will return a new object or array with all falsy values removed."],"code":[{"lang":"js","text":"const compactObject = (val) => {\n  const data = Array.isArray(val) ? val.filter(Boolean) : val;\n  return Object.keys(data).reduce(\n    (acc, key) => {\n      const value = data[key];\n      if (Boolean(value))\n        acc[key] = typeof value === \"object\" ? compactObject(value) : value;\n      return acc;\n    },\n    Array.isArray(val) ? [] : {}\n  );\n};"},{"lang":"js","text":"const obj = {\n  a: null,\n  b: false,\n  c: true,\n  d: 0,\n  e: 1,\n  f: \"\",\n  g: \"a\",\n  h: [null, false, \"\", true, 1, \"a\"],\n  i: { j: 0, k: false, l: \"a\" }\n};\ncompactObject(obj);\n// { c: true, e: 1, g: 'a', h: [ true, 1, 'a' ], i: { l: 'a' } }"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const obj = {\n  a: null,\n  b: false,\n  c: true,\n  d: 0,\n  e: 1,\n  f: \"\",\n  g: \"a\",\n  h: [null, false, \"\", true, 1, \"a\"],\n  i: { j: 0, k: false, l: \"a\" }\n};\ncompactObject(obj);\n// { c: true, e: 1, g: 'a', h: [ true, 1, 'a' ], i: { l: 'a' } }"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-compact-whitespaces-in-javascript-strings":{"intro":"In this lab, we will explore how to compact whitespaces in a string using JavaScript. We will utilize the String.prototype.replace() method and a regular expression to replace all occurrences of two or more whitespace characters with a single space. This will help us to effectively format and clean up text data in our web applications.","steps":[{"title":"Compact Whitespaces","body":["Function to Compact Whitespaces in a String","To compact whitespaces in a string, use the compactWhitespace() function.","• It uses String.prototype.replace() with a regular expression to replace all occurrences of 2 or more whitespace characters with a single space. • The function takes a string as an argument and returns the compacted string."],"code":[{"lang":"js","text":"const compactWhitespace = (str) => str.replace(/\\s{2,}/g, \" \");"},{"lang":"js","text":"compactWhitespace(\"Lorem    Ipsum\"); // 'Lorem Ipsum'\ncompactWhitespace(\"Lorem \\n Ipsum\"); // 'Lorem Ipsum'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"compactWhitespace(\"Lorem    Ipsum\"); // 'Lorem Ipsum'\ncompactWhitespace(\"Lorem \\n Ipsum\"); // 'Lorem Ipsum'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-function-composition-in-javascript":{"intro":"In this lab, we will explore the concept of function composition in JavaScript. We will learn how to combine multiple functions to create a new function, and how to use the compose() function to perform right-to-left function composition. Through hands-on examples and exercises, we will gain a deeper understanding of this powerful technique and its practical applications in programming.","steps":[{"title":"Compose Functions","body":["How to Compose Functions in JavaScript","Here's an example of how to perform right-to-left function composition in JavaScript:","• Use Array.prototype.reduce() to perform right-to-left function composition. • The last (rightmost) function can accept one or more arguments; the remaining functions must be unary. • Define the compose function that will take any number of functions as arguments and return a new function that composes them. • Call the compose function with the desired functions in the desired order. • Call the new composed function with any necessary arguments.","For example, let's say we have two functions:"],"code":[{"lang":"js","text":"const compose = (...fns) =>\n  fns.reduce(\n    (f, g) =>\n      (...args) =>\n        f(g(...args))\n  );"},{"lang":"js","text":"const add5 = (x) => x + 5;\nconst multiply = (x, y) => x * y;"},{"lang":"js","text":"const multiplyAndAdd5 = compose(add5, multiply);"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const multiplyAndAdd5 = compose(add5, multiply);"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-consecutive-element-subarrays":{"intro":"In this lab, we will explore the concept of creating consecutive element subarrays using JavaScript. The goal of this lab is to learn how to create an array of n-tuples of consecutive elements using the Array.prototype.slice() and Array.prototype.map() methods in JavaScript. Through practical examples, we will understand how to populate the array with n-tuples of consecutive elements from an input array and return an empty array if n is greater than the length of the input array.","steps":[{"title":"Consecutive Element Subarrays","body":["• Call aperture(n, arr) function with n as the number of consecutive elements and arr as the array of numbers. • The function returns an array of n-tuples of consecutive elements from arr. • If n is greater than the length of arr, the function returns an empty array."],"code":[{"lang":"js","text":"const aperture = (n, arr) =>\n  n > arr.length ? [] : arr.slice(n - 1).map((v, i) => arr.slice(i, i + n));"},{"lang":"js","text":"aperture(2, [1, 2, 3, 4]); // [[1, 2], [2, 3], [3, 4]]\naperture(3, [1, 2, 3, 4]); // [[1, 2, 3], [2, 3, 4]]\naperture(5, [1, 2, 3, 4]); // []"}]}],"commands":[],"reference":[{"path":"reference.js","text":"aperture(2, [1, 2, 3, 4]); // [[1, 2], [2, 3], [3, 4]]\naperture(3, [1, 2, 3, 4]); // [[1, 2, 3], [2, 3, 4]]\naperture(5, [1, 2, 3, 4]); // []"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-string-contains-whitespace":{"intro":"In this lab, we will explore how to check if a given string contains any whitespace characters using regular expressions in JavaScript. The lab will provide a step-by-step guide on how to use the RegExp.prototype.test() method to check if a string contains any whitespace characters. By the end of this lab, you will have a better understanding of how to check for whitespace characters in JavaScript strings.","steps":[{"title":"Check if String Contains Whitespace","body":["Checking for Whitespace in a String","To check if a string contains whitespace characters, follow the steps below:","• To test the function, call containsWhitespace with a string as an argument. It will return true if the string contains whitespace characters, otherwise false."],"code":[{"lang":"js","text":"const containsWhitespace = (str) => /\\s/.test(str);"},{"lang":"js","text":"containsWhitespace(\"lorem\"); // false\n  containsWhitespace(\"lorem ipsum\"); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"containsWhitespace(\"lorem\"); // false\n  containsWhitespace(\"lorem ipsum\"); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-convert-function-to-variadic":{"intro":"In this lab, we will explore how to convert a function that accepts an array into a variadic function using JavaScript. We will achieve this by creating a closure that collects all inputs into an array-accepting function. By the end of the lab, you will have a better understanding of how to manipulate functions in JavaScript to make them more versatile and adaptable to different use cases.","steps":[{"title":"Convert Function to Variadic","body":["Converting a Function to a Variadic Function","To convert a function that accepts an array into a variadic function, you can follow these steps:","• Return a closure that collects all inputs into an array-accepting function.","• Use the collectInto function to convert a function to a variadic function."],"code":[{"lang":"js","text":"const collectInto =\n  (fn) =>\n  (...args) =>\n    fn(args);"},{"lang":"js","text":"const Pall = collectInto(Promise.all.bind(Promise));\nlet p1 = Promise.resolve(1);\nlet p2 = Promise.resolve(2);\nlet p3 = new Promise((resolve) => setTimeout(resolve, 2000, 3));\nPall(p1, p2, p3).then(console.log); // [1, 2, 3] (after about 2 seconds)"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const Pall = collectInto(Promise.all.bind(Promise));\nlet p1 = Promise.resolve(1);\nlet p2 = Promise.resolve(2);\nlet p3 = new Promise((resolve) => setTimeout(resolve, 2000, 3));\nPall(p1, p2, p3).then(console.log); // [1, 2, 3] (after about 2 seconds)"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-convert-map-to-object":{"intro":"In this lab, we will explore how to convert a Map to an object in JavaScript. We will use the Map.prototype.entries() method to get an array of key-value pairs from the Map and then use Object.fromEntries() to convert the array to an object. This lab will provide a better understanding of the use of Map and Object in JavaScript.","steps":[{"title":"Convert Map to Object","body":["Instructions for Converting Map to Object in JavaScript","To convert a JavaScript Map to an object, follow these steps:","Here is an example code snippet for converting a Map to an object:","To test the function, you can run:"],"code":[{"lang":"js","text":"const mapToObject = (map) => Object.fromEntries(map.entries());"},{"lang":"js","text":"mapToObject(\n  new Map([\n    [\"a\", 1],\n    [\"b\", 2]\n  ])\n); // {a: 1, b: 2}"}]}],"commands":[],"reference":[{"path":"reference.js","text":"mapToObject(\n  new Map([\n    [\"a\", 1],\n    [\"b\", 2]\n  ])\n); // {a: 1, b: 2}"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-convert-object-to-map":{"intro":"In this lab, we will explore how to convert an object to a Map in JavaScript. We will use the Object.entries() method to convert the object to an array of key-value pairs, and then use the Map constructor to convert the array to a Map. This technique can be useful when working with data that requires the use of a Map data structure.","steps":[{"title":"Convert Object to Map","body":["Here's how to Convert Object to Map","To convert an object to a Map, follow these steps:","Here's an example code snippet:","You can use the objectToMap() function to convert an object to a Map. For example:"],"code":[{"lang":"js","text":"const objectToMap = (obj) => new Map(Object.entries(obj));"},{"lang":"js","text":"objectToMap({ a: 1, b: 2 }); // Map {'a' => 1, 'b' => 2}"}]}],"commands":[],"reference":[{"path":"reference.js","text":"objectToMap({ a: 1, b: 2 }); // Map {'a' => 1, 'b' => 2}"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-convert-to-absolute-path":{"intro":"In this lab, we will dive into the world of JavaScript programming and explore how to convert tilde paths to absolute paths using various techniques. You will learn how to use regular expressions, the String.prototype.replace() method, and the os.homedir() function to accomplish this task. By the end of this lab, you will have a solid understanding of how to convert tilde paths to absolute paths using JavaScript.","steps":[{"title":"Convert to Absolute Path","body":["How to Convert a Tilde Path to an Absolute Path in Node.js","The code uses String.prototype.replace() with a regular expression and os.homedir() to replace the ~ at the beginning of the path with the home directory. Here is an example of how to use the untildify function:"],"code":[{"lang":"js","text":"const untildify = (str) =>\n  str.replace(/^~($|\\/|\\\\)/, `${require(\"os\").homedir()}$1`);"},{"lang":"js","text":"untildify(\"~/node\"); // returns '/Users/aUser/node'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"untildify(\"~/node\"); // returns '/Users/aUser/node'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-copy-sign-to-number":{"intro":"In this lab, we will explore the copySign function in JavaScript, which returns the absolute value of the first number but with the sign of the second number. We will learn how to use the Math.sign() method to check for the sign of the two numbers and how to conditionally return the appropriate value. By the end of this lab, you will have a better understanding of how to manipulate numbers in JavaScript.","steps":[{"title":"Copy Sign to Number","body":["Function to Copy the Sign of One Number to Another","The copySign function returns the absolute value of the first number, but with the sign of the second number. To accomplish this:","• Use Math.sign() to check if the two numbers have the same sign. • Return x if they do, -x otherwise.","Here is the code for the copySign function:"],"code":[{"lang":"js","text":"const copySign = (x, y) => (Math.sign(x) === Math.sign(y) ? x : -x);"},{"lang":"js","text":"copySign(2, 3); // 2\ncopySign(2, -3); // -2\ncopySign(-2, 3); // 2\ncopySign(-2, -3); // -2"}]}],"commands":[],"reference":[{"path":"reference.js","text":"copySign(2, 3); // 2\ncopySign(2, -3); // -2\ncopySign(-2, 3); // 2\ncopySign(-2, -3); // -2"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-group-elements-by-count":{"intro":"In this lab, we will learn about the countBy function, which is used to group the elements of an array based on the given function and returns the count of elements in each group. We will explore how this function can be used to map values of an array to a function or property name and how to create an object to count the elements in each group using Array.prototype.reduce(). We will also look at several examples to understand how to use this function in real-world scenarios.","steps":[{"title":"Count Grouped Elements","body":["How to Group and Count Elements in an Array Using JavaScript","To group and count elements in an array using JavaScript, follow these steps:","You can test the countBy function with the following examples:"],"code":[{"lang":"js","text":"const countBy = (arr, fn) =>\n  arr\n    .map(typeof fn === \"function\" ? fn : (val) => val[fn])\n    .reduce((acc, val) => {\n      acc[val] = (acc[val] || 0) + 1;\n      return acc;\n    }, {});"},{"lang":"js","text":"countBy([6.1, 4.2, 6.3], Math.floor); // {4: 1, 6: 2}\ncountBy([\"one\", \"two\", \"three\"], \"length\"); // {3: 2, 5: 1}\ncountBy([{ count: 5 }, { count: 10 }, { count: 5 }], (x) => x.count); // {5: 2, 10: 1}"}]}],"commands":[],"reference":[{"path":"reference.js","text":"countBy([6.1, 4.2, 6.3], Math.floor); // {4: 1, 6: 2}\ncountBy([\"one\", \"two\", \"three\"], \"length\"); // {3: 2, 5: 1}\ncountBy([{ count: 5 }, { count: 10 }, { count: 5 }], (x) => x.count); // {5: 2, 10: 1}"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-fundamental-javascript-programming-concepts":{"intro":"In this lab, we will explore the fundamental concepts of JavaScript programming. You will learn how to write basic JavaScript code and gain an understanding of variables, data types, functions, and control structures. By the end of this lab, you will have a solid foundation in JavaScript programming and be able to apply your knowledge to solve real-world problems.","steps":[{"title":"Count Occurrences","body":["How to Count Occurrences in JavaScript","To count the number of times a specific value occurs in a JavaScript array, you can use the Array.prototype.reduce() method.","• In the code above, the countOccurrences function takes two arguments: the array to search and the value to count. • The reduce() method is used to loop through each element in the array and increment a counter each time the specific value is encountered. • To test the function, call it with an array and a value, like this:","This will return the number of times 1 occurs in the array [1, 1, 2, 1, 2, 3], which is 3."],"code":[{"lang":"js","text":"const countOccurrences = (arr, val) =>\n  arr.reduce((a, v) => (v === val ? a + 1 : a), 0);"},{"lang":"js","text":"countOccurrences([1, 1, 2, 1, 2, 3], 1); // 3"}]}],"commands":[],"reference":[{"path":"reference.js","text":"countOccurrences([1, 1, 2, 1, 2, 3], 1); // 3"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-count-substrings-of-string":{"intro":"In this lab, we will explore the concept of counting substrings of a string using JavaScript. We will create a function that takes in a string and a search value and returns the number of times the search value appears in the string. This lab will help you understand the fundamentals of string manipulation in JavaScript and improve your problem-solving skills.","steps":[{"title":"Count Substrings of String","body":["How to Count Substrings in a String using JavaScript","To use this function, follow these steps:","• Declare a function called countSubstrings that takes two parameters: str and searchValue. • Initialize two variables: count and i. • Use the Array.prototype.indexOf() method to search for searchValue in str. • If the value is found, increment the count variable and update the i variable. • Use a while loop that returns as soon as the value returned from Array.prototype.indexOf() is -1. • Return the count variable.","Here's the code for the countSubstrings function:"],"code":[{"lang":"js","text":"const countSubstrings = (str, searchValue) => {\n  let count = 0,\n    i = 0;\n  while (true) {\n    const r = str.indexOf(searchValue, i);\n    if (r !== -1) [count, i] = [count + 1, r + 1];\n    else return count;\n  }\n};"},{"lang":"js","text":"countSubstrings(\"tiktok tok tok tik tok tik\", \"tik\"); // 3\ncountSubstrings(\"tutut tut tut\", \"tut\"); // 4"}]}],"commands":[],"reference":[{"path":"reference.js","text":"countSubstrings(\"tiktok tok tok tik tok tik\", \"tik\"); // 3\ncountSubstrings(\"tutut tut tut\", \"tut\"); // 4"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-create-event-hub":{"intro":"In this lab, we will be working with JavaScript to create an event hub using the publish-subscribe pattern. The event hub will have methods such as emit, on, and off to allow for subscribing to and emitting events. This lab will provide hands-on experience in building a powerful tool that can be used to manage complex events in JavaScript applications.","steps":[{"title":"Create Event Hub","body":["To create an event hub with emit, on, and off methods, follow the steps:","• Use Object.create(null) to create an empty hub object that does not inherit properties from Object.prototype. • For emit, resolve the array of handlers based on the event argument and then run each one with Array.prototype.forEach() by passing in the data as an argument. • For on, create an array for the event if it does not yet exist, then use Array.prototype.push() to add the handler to the array. • For off, use Array.prototype.findIndex() to find the index of the handler in the event array and remove it using Array.prototype.splice().","• Subscribe to events by listening for different types of events using on(). • Publish events to invoke all handlers subscribed to them, passing the data to them as an argument using emit(). • Unsubscribe to an event by stopping a specific handler from listening to the event using off()."],"code":[{"lang":"js","text":"const createEventHub = () => ({\n  hub: Object.create(null),\n  emit(event, data) {\n    (this.hub[event] || []).forEach((handler) => handler(data));\n  },\n  on(event, handler) {\n    if (!this.hub[event]) this.hub[event] = [];\n    this.hub[event].push(handler);\n  },\n  off(event, handler) {\n    const i = (this.hub[event] || []).findIndex((h) => h === handler);\n    if (i > -1) this.hub[event].splice(i, 1);\n    if (this.hub[event].length === 0) delete this.hub[event];\n  }\n});"},{"lang":"js","text":"const handler = (data) => console.log(data);\nconst hub = createEventHub();\nlet increment = 0;\n\n// Subscribe: listen for different types of events\nhub.on(\"message\", handler);\nhub.on(\"message\", () => console.log(\"Message event fired\"));\nhub.on(\"increment\", () => increment++);\n\n// Publish: emit events to invoke all handlers subscribed to them, passing the data to them as an argument\nhub.emit(\"message\", \"hello world\"); // logs 'hello world' and 'Message event fired'\nhub.emit(\"message\", { hello: \"world\" }); // logs the object and 'Message event fired'\nhub.emit(\"increment\"); // `increment` variable is now 1\n\n// Unsubscribe: stop a specific handler from listening to the 'message' event\nhub.off(\"message\", handler);"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const handler = (data) => console.log(data);\nconst hub = createEventHub();\nlet increment = 0;\n\n// Subscribe: listen for different types of events\nhub.on(\"message\", handler);\nhub.on(\"message\", () => console.log(\"Message event fired\"));\nhub.on(\"increment\", () => increment++);\n\n// Publish: emit events to invoke all handlers subscribed to them, passing the data to them as an argument\nhub.emit(\"message\", \"hello world\"); // logs 'hello world' and 'Message event fired'\nhub.emit(\"message\", { hello: \"world\" }); // logs the object and 'Message event fired'\nhub.emit(\"increment\"); // `increment` variable is now 1\n\n// Unsubscribe: stop a specific handler from listening to the 'message' event\nhub.off(\"message\", handler);"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-cross-product-of-arrays":{"intro":"In this lab, we will explore how to create a new array out of the two supplied by generating every possible pair from the elements of the two arrays. We will use JavaScript's built-in methods such as reduce(), map(), and concat() to achieve this. By the end of this lab, you will have a good understanding of how to work with arrays in JavaScript.","steps":[{"title":"Cross Product of Arrays","body":["Creating an Array Cross Product in JavaScript","To create an array cross product in JavaScript, follow these steps:","This will return an array containing all possible pairs of elements from the two input arrays."],"code":[{"lang":"js","text":"const xProd = (a, b) =>\n  a.reduce((acc, x) => acc.concat(b.map((y) => [x, y])), []);\n\nxProd([1, 2], [\"a\", \"b\"]); // [[1, 'a'], [1, 'b'], [2, 'a'], [2, 'b']]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const xProd = (a, b) =>\n  a.reduce((acc, x) => acc.concat(b.map((y) => [x, y])), []);\n\nxProd([1, 2], [\"a\", \"b\"]); // [[1, 'a'], [1, 'b'], [2, 'a'], [2, 'b']]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-csv-to-array":{"intro":"In this lab, we will explore how to convert comma-separated values (CSV) data into a 2D array using JavaScript. We will use the CSVToArray() function which takes a CSV string as input and converts it into an array of arrays. This lab will help you understand how to work with CSV data and manipulate it using JavaScript.","steps":[{"title":"CSV to Array","body":["To convert a comma-separated values (CSV) string to a 2D array, follow these steps:","Here's the code to convert CSV to an array:","You can use the following examples to test the function:"],"code":[{"lang":"js","text":"const CSVToArray = (data, delimiter = \",\", omitFirstRow = false) =>\n  data\n    .slice(omitFirstRow ? data.indexOf(\"\\n\") + 1 : 0)\n    .split(\"\\n\")\n    .map((v) => v.split(delimiter));"},{"lang":"js","text":"CSVToArray(\"a,b\\nc,d\"); // [['a', 'b'], ['c', 'd']];\nCSVToArray(\"a;b\\nc;d\", \";\"); // [['a', 'b'], ['c', 'd']];\nCSVToArray(\"col1,col2\\na,b\\nc,d\", \",\", true); // [['a', 'b'], ['c', 'd']];"}]}],"commands":[],"reference":[{"path":"reference.js","text":"CSVToArray(\"a,b\\nc,d\"); // [['a', 'b'], ['c', 'd']];\nCSVToArray(\"a;b\\nc;d\", \";\"); // [['a', 'b'], ['c', 'd']];\nCSVToArray(\"col1,col2\\na,b\\nc,d\", \",\", true); // [['a', 'b'], ['c', 'd']];"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-csv-to-json":{"intro":"In this lab, we will explore how to convert a comma-separated values (CSV) string to a 2D array of objects using JavaScript. We will use various string manipulation methods such as split() and slice() along with array methods like reduce() and map() to achieve this conversion. This lab will help you understand how to work with CSV data in JavaScript and how to manipulate it into a format that can be easily processed.","steps":[{"title":"CSV to JSON","body":["• Use Array.prototype.indexOf() to find the first newline character (\\n). • Use Array.prototype.slice() to remove the first row (title row) and String.prototype.split() to separate it into values, using the provided delimiter. • Use String.prototype.split() to create a string for each row. • Use String.prototype.split() to separate the values in each row, using the provided delimiter. • Use Array.prototype.reduce() to create an object for each row's values, with the keys parsed from the title row. • Omit the second argument, delimiter, to use a default delimiter of ,.","To test the function, use the following examples:"],"code":[{"lang":"js","text":"const CSVToJSON = (data, delimiter = \",\") => {\n  const titles = data.slice(0, data.indexOf(\"\\n\")).split(delimiter);\n  return data\n    .slice(data.indexOf(\"\\n\") + 1)\n    .split(\"\\n\")\n    .map((v) => {\n      const values = v.split(delimiter);\n      return titles.reduce(\n        (obj, title, index) => ((obj[title] = values[index]), obj),\n        {}\n      );\n    });\n};"},{"lang":"js","text":"CSVToJSON(\"col1,col2\\na,b\\nc,d\");\n// [{'col1': 'a', 'col2': 'b'}, {'col1': 'c', 'col2': 'd'}];\nCSVToJSON(\"col1;col2\\na;b\\nc;d\", \";\");\n// [{'col1': 'a', 'col2': 'b'}, {'col1': 'c', 'col2': 'd'}];"}]}],"commands":[],"reference":[{"path":"reference.js","text":"CSVToJSON(\"col1,col2\\na,b\\nc,d\");\n// [{'col1': 'a', 'col2': 'b'}, {'col1': 'c', 'col2': 'd'}];\nCSVToJSON(\"col1;col2\\na;b\\nc;d\", \";\");\n// [{'col1': 'a', 'col2': 'b'}, {'col1': 'c', 'col2': 'd'}];"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-javascript-currying-techniques":{"intro":"In this lab, we will be exploring the concept of currying in JavaScript. Currying is a technique that allows us to transform a function that takes multiple arguments into a sequence of functions that each take a single argument. Through this lab, you will gain a deeper understanding of how currying works and how it can be applied in your JavaScript code.","steps":[{"title":"Curry Function","body":["To curry a function, follow these steps:"],"code":[{"lang":"js","text":"const curry = (fn, arity = fn.length, ...args) =>\n  arity <= args.length ? fn(...args) : curry.bind(null, fn, arity, ...args);"},{"lang":"js","text":"curry(Math.pow)(2)(10); // 1024\ncurry(Math.min, 3)(10)(50)(2); // 2"}]}],"commands":[],"reference":[{"path":"reference.js","text":"curry(Math.pow)(2)(10); // 1024\ncurry(Math.min, 3)(10)(50)(2); // 2"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"}};
